using System.Collections.Generic;
using UnityEngine;

namespace Game.Gameplay
{
    // Item icon registry. Sprites are generated by the editor script ItemIconBuilder into Resources/Icons/<key>.png.
    // Missing icons return null; the inventory UI then shows its fallback plate.
    public static class ItemIcons
    {
        public static readonly string[] KnownKeys =
        {
            "weapon_1", "weapon_2", "weapon_3", "weapon_4", "weapon_5",
            "weapon_6", "weapon_7", "weapon_8", "weapon_9", "weapon_10", "weapon_11", "weapon_12", "weapon_13", "weapon_14", "weapon_15", "weapon_16", "weapon_31", "weapon_32", "weapon_33", "weapon_34", "weapon_35", // ADR-217
            "weapon_21", "weapon_22", "weapon_23", "weapon_24", // melee (ADR-073)
            "ammo_9mm", "ammo_556", "ammo_762", "ammo_12ga",
            "medkit",
            "helmet_1", "helmet_2", "helmet_3",
            "vest_1", "vest_2", "vest_3",
            "grenade",
            "optic_reddot", "optic_holo", "optic_2x", "optic_3x", "optic_4x", "optic_6x", "optic_8x", "optic_15x",
            "bandage", "firstaid", "smoke", "key",
            "jerrycan", // ADR-075
            "drink", "pill", "syringe", // ADR-099
            "flash", // ADR-105
            "molotov", // ADR-110
            "backpack_1", "backpack_2", "backpack_3", // ADR-091
            "att_grip_v", "att_grip_a", "att_grip_c", "att_stock", // ADR-100
            "att_comp", "att_flash", "att_supp", "att_mag", // ADR-102
        };

        // "backpack_2"; empty for no such tier.
        public static string BackpackKey(int tier) => tier >= 1 && tier <= 3 ? "backpack_" + tier : "";

        // Icon key of an optic or attachment by its id (1..8 optics, 9..16 ADR-100); empty for none or unknown.
        static readonly string[] OpticKeys =
        {
            "", "optic_reddot", "optic_holo", "optic_2x", "optic_3x", "optic_4x", "optic_6x", "optic_8x", "optic_15x",
            "att_comp", "att_flash", "att_supp", "att_grip_v", "att_grip_a", "att_grip_c", "att_stock", "att_mag",
        };

        public static string OpticKey(int opticId) => opticId > 0 && opticId < OpticKeys.Length ? OpticKeys[opticId] : "";

        // Caches misses too (stored as null) so repeated lookups never hit Resources again.
        static readonly Dictionary<string, Sprite> Cache = new Dictionary<string, Sprite>();

        public static Sprite Get(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            if (Cache.TryGetValue(key, out var cached))
            {
                if (cached != null) return cached;
                if ((object)cached == null) return null; // a real miss; a destroyed sprite falls through and reloads
            }
            var sprite = System.Array.IndexOf(KnownKeys, key) >= 0 ? Resources.Load<Sprite>("Icons/" + key) : null;
            Cache[key] = sprite;
            return sprite;
        }
    }
}
